UNITS = [
 dict(id='B2-01',title='Reconstituir um projeto e negociar previsões',prerequisites=['B1-01','B1-02','B1-03'],reading_questions=5,
 goal='Comparar planejamento antigo, trabalho realizado e previsão atual; comunicar prazos sem transformar expectativas em fatos.',
 targets=['Past perfect contínuo','Futuro contínuo e perfeito','Futuro no passado'],
 support='proof = prova editorial; caption = legenda; supplier = fornecedor; estimate = estimativa; revised schedule = cronograma revisto; binding = encadernação; by Friday = até sexta; throughout = durante todo um período; guarantee = garantia. Todos os textos descrevem uma editora comunitária fictícia.',
 explanation='Had been + -ing destaca duração até um ponto passado: We had been checking captions for two hours when the new file arrived. Had checked destaca resultado: We had checked six captions. Was/were going to e would podem apresentar planos ou previsões vistos do passado: We were going to print on Tuesday; the supplier said it would arrive on Monday. Não comprovam realização. Will be + -ing apresenta atividade em determinado momento futuro; will have + particípio apresenta conclusão prevista até um marco: At ten we’ll be checking proofs; by noon we’ll have checked them. A forma gramatical não garante que a previsão se cumpra. Identifique condições e fonte.',
 readings=[('Nota da editora na quarta-feira — ficção','We are preparing a booklet of local photographs. Last week we were going to send the final file to the printer on Tuesday. The supplier said the paper would arrive on Monday, so we expected to collect the booklet on Friday. That was the original schedule, not a record of what happened.\nOn Monday afternoon, our team had been checking captions for two hours when a contributor sent a corrected photograph. We had checked six captions, but the correction affected one of them. We reopened that caption and replaced the photograph. By the end of Monday, all captions had been checked again. The final file was sent on Tuesday as planned.\nThe paper did not arrive on Monday. It arrived on Wednesday morning. The printer now expects to prepare a proof on Thursday. At ten on Thursday, our two editors will be checking that proof together. If there are no new problems, they expect to have approved it by noon. Printing and binding would then follow. Friday collection is no longer promised.'),('Resposta do impressor','Thank you for separating the completed work from the new estimate. We have received your file and the paper is now here. However, the printing slot depends on proof approval. If approval reaches us by noon on Thursday, we expect to finish printing by Friday afternoon. Binding will still be needed. We estimate that the bound copies will be ready on Monday, but that is not yet a guaranteed collection date.\nPlease do not announce that the books will be ready on Friday. That date refers to the expected end of printing, not to completed binding. Nor should the earlier message be read as proof that the paper arrived on Monday: it described what the supplier expected.\nWe can send an update after proof approval. If another correction is needed, we will revise the schedule again. Our purpose is to give readers a useful estimate with its conditions, rather than an exact date unsupported by the current production stage.')],
 audio='Editor: Had you been checking the captions long when the photograph arrived?\nReader: For two hours. Six captions had been checked, but we reopened one.\nEditor: What will you be doing at ten tomorrow?\nReader: Checking the proof with Jo. We expect to have approved it by noon if no new correction is needed.\nEditor: So readers can collect the booklets on Friday?\nReader: No. Friday is the estimated end of printing. Binding comes afterwards.\nEditor: And Monday collection?\nReader: An estimate, not a guarantee. We’ll ask for an update after approval.',
 questions=[('O envio do arquivo ocorreu conforme plano?', 'Sim, na terça; atraso do papel é etapa distinta.'),('Por que uma legenda já verificada foi reaberta?','Nova foto corrigida afetou essa legenda.'),('O que ocorreu de fato na quarta?','O papel chegou; não significa que os livros ficaram prontos.'),('Que condição sustenta previsão de impressão até sexta?','Aprovação da prova até quinta ao meio-dia.'),('Por que segunda ainda não pode ser anunciada como garantida?','É estimativa de cópias encadernadas; depende das etapas anteriores.'),('Na escuta, quanto durava a verificação antes da foto?','Duas horas.'),('O que os editores farão às dez?','Estarão conferindo a prova juntos.'),('Qual atualização pedirão?','Estado e cronograma após aprovação da prova.')],
 practice=[('Complete: We ___ captions for two hours when the photo arrived. (check)','had been checking; duração anterior ao evento.'),('Contraste We had checked six captions com had been checking captions.','Primeira quantifica resultados; segunda destaca atividade, sem total concluído.'),('Reescreva plano passado não realizado: We plan to collect on Friday.','We were going to collect on Friday; o contexto informa que não se manteve.'),('Relate previsão de segunda feita na semana anterior: The supplier said the paper ___.','would arrive on Monday.'),('Complete atividade futura às dez: We ___ the proof. (check)','will be checking.'),('Complete conclusão prevista até meio-dia: We expect we ___ it. (approve)','will have approved; é expectativa.'),('Corrija inferência: They will have finished printing by Friday, so binding is finished too.','Printing and binding are separate stages; binding is still needed.'),('Redija previsão condicionada à ausência de correções.','If no new corrections are needed, we expect to have approved the proof by noon.')],
 guided='A recebe a nota editorial; B recebe resposta do impressor. Sem mostrar cartões, reconstruam linha do tempo com plano, realização e previsão. A pede uma data para divulgação; B explica qual etapa pode prever e qual informação falta. Troquem papéis e revisem uma mensagem que erroneamente anuncia coleta na sexta.',
 model='A: We were going to collect the booklets on Friday. Is that still possible?\nB: Friday refers to printing now, not collection. At ten on Thursday, you’ll be checking the proof. If it is approved by noon, we expect printing to finish on Friday.\nA: Can I promise Monday?\nB: Please describe it as an estimate until we confirm.\nModelo escrito: The file was sent on Tuesday, but the paper arrived on Wednesday. The editors will be checking the proof at ten on Thursday. They expect to have approved it by noon, provided no further correction is needed. Friday is the estimated end of printing; binding follows. We will request a new update after approval before confirming collection.',
 transfer='Novo cenário fictício: equipe preparava legendas de um filme havia três horas quando recebeu entrevista corrigida na terça. O plano anterior era publicar quinta. Revisão concluída quarta; áudio ainda não mixado. Sexta às 9h ocorrerá mixagem; equipe espera concluí-la até 13h se não houver ruído. Exportação e conferência final vêm depois, sem duração confirmada. Escreva atualização de aproximadamente 150–190 palavras e explique a um colega por que sexta às 13h não é prazo confirmado de publicação. Extensão orientativa, não nota de corte.',
 evidence='Manter terça correção, quarta revisão, sexta atividade/expectativa condicionada; não inventar duração de exportação ou publicação. Usar duração anterior, plano passado e previsão atual com fontes e limites.',
 review='Em outro encontro: tradução em andamento havia quatro dias quando novo capítulo chegou; entrega prevista para ontem não ocorreu; amanhã às 14h haverá revisão, com conclusão estimada até 17h; aprovação do autor ainda pendente. Produza três frases de atualização e indique pendência.',
 review_answer='We had been translating for four days when the new chapter arrived. We were going to deliver yesterday, but didn’t. Tomorrow at two we’ll be reviewing the translation and expect to have finished by five. Author approval is still pending; entrega final não garantida.',
 phon='Organize a fala em blocos: BY FRIDAY / PRINTING; AFTER THAT / BINDING. O colega reconstrói a sequência. Pratique had been e will have em contexto, sem apagar o particípio que distingue resultado.',
 teacher='Antes da leitura, peça distinguir plano, atividade e resultado em português. Depois compare as formas inglesas. Dificuldade previsível: traduzir havia por had isolado e usar futuro perfeito como promessa inevitável. Aceite reformulação natural se mantém tempo e condição; registre separadamente uso das formas-alvo. Distribua em dois encontros se a carga impedir comparação. Fontes são ficção, não prazo real de produção Lexio.'),
 dict(id='B2-02',title='Discutir alternativas passadas sem confundir hipótese e culpa',prerequisites=['B2-01','B1-04','B1-08'],reading_questions=5,
 goal='Distinguir fatos, alternativas contrafactuais e consequências atuais; formular arrependimentos e propostas de reparação sem inventar causas.',
 targets=['Terceira condicional','Condicionais mistas','Wish e if only'],
 support='backup = cópia de segurança; venue = local; regret = arrependimento; outcome = resultado; restore = restaurar; take responsibility = assumir responsabilidade; misleading = enganoso no efeito, sem provar intenção; outage = interrupção. Could have = poderia ter; would have = teria no cenário hipotético.',
 explanation='If + had + particípio, would have + particípio imagina passado diferente: If we had downloaded the file, we would have had a local copy. Não descreve fato ocorrido. Could/might have deixam possibilidade: We might have finished earlier. Condicional mista pode ligar passado e presente: If we had saved the file, we would have it now. Também um estado atual mais geral pode enquadrar passado: If I were more confident with the equipment, I would have offered to help yesterday. A frase apresenta a interpretação do falante, não prova causal. Wish + passado expressa desejo contrário ao presente: I wish we had a backup now. Wish + past perfect trata passado: I wish we had saved it. If only enfatiza desejo/arrependimento; não substitui investigação de fatos.',
 readings=[('Relato de um encontro de cinema — ficção','Our discussion group planned to show a short film on Saturday. We had permission to screen it, but the organiser kept the only available copy in an online folder. Nobody downloaded it before the meeting. At seven, the internet connection at the venue stopped working. We could not open the folder, so we discussed photographs from the film instead. The film screening did not happen that evening.\nLooking back, I wish we had downloaded the permitted copy beforehand. If we had done so, we would have had a local file available. That does not prove the whole evening would have gone perfectly: we had not tested the sound system either. A local file would have removed one obstacle, not every possible obstacle.\nThe folder is still inaccessible today, and we have no local copy. If we had saved the file on Friday, we would have it now. I wish we had a clear backup procedure. We can create one before the next meeting, but we should not describe that future procedure as something that already existed.'),('Resposta de outro participante','I agree that a local copy would have helped, provided it was covered by the permission we had. However, I disagree with the message saying that the organiser deliberately ruined the event. The account tells us that the copy was online and the connection failed. It gives us no evidence of deliberate sabotage.\nI also regret not offering technical help. If I were more confident with the equipment, I would have offered to test it before the meeting. That is my reflection on my own confidence; it is not proof that my help would have prevented the outage. If only we had checked the sound system as well. We might have discovered another issue in advance, or we might have found it working normally. We cannot know which from the current record.\nFor the next event, I suggest a short checklist with named responsibilities: confirm permission, obtain the appropriate file, test playback and agree an alternative activity. We should test that plan rather than promise that no problem can ever happen again.')],
 audio='Host: If we had downloaded the file, would the whole event have been perfect?\nGuest: We would have had a local copy, but we hadn’t tested the sound. We can’t guarantee the rest.\nHost: What do you wish had happened?\nGuest: I wish we had checked both the file and the equipment.\nHost: And what do you wish were different now?\nGuest: I wish we had a backup procedure. We still don’t.\nHost: Does the missing copy prove someone caused the failure deliberately?\nGuest: No. We should discuss responsibilities without inventing intentions.',
 questions=[('Quais fatos impediram abrir a pasta naquela noite?','Conexão parou e cópia disponível estava online; nenhuma baixada.'),('Que atividade substituiu a exibição?','Discussão de fotografias do filme.'),('Uma cópia local garantiria noite perfeita?','Não; som não testado e demais condições não garantidas.'),('Que consequência presente é ligada ao passado?','Ainda não ter cópia local hoje; salvar sexta teria permitido tê-la agora.'),('Por que a acusação de intenção é rejeitada?','Relato não oferece evidência de sabotagem deliberada.'),('Na escuta, qual arrependimento envolve passado?','Não ter conferido arquivo e equipamento.'),('Qual desejo envolve estado atual?','Ter procedimento de backup, ainda inexistente.'),('O que a conversa propõe evitar ao discutir responsabilidades?','Inventar intenções ou garantir resultados não demonstrados.')],
 practice=[('Complete: If we ___ the file, we would have had a copy. (download)','had downloaded.'),('A frase anterior afirma que baixaram o arquivo?','Não; é contrafactual no cenário dado.'),('Complete consequência atual: If we had saved it, we ___ it now. (have)','would have.'),('Expresse arrependimento de não testar: I wish we ___.','had tested the equipment.'),('Expresse desejo de ter procedimento agora: I wish we ___.','had a backup procedure; had simples, não had had para este sentido presente.'),('Explique diferença entre would have had a copy e might have finished earlier.','Primeira apresenta consequência na hipótese; segunda possibilidade, sem certeza de terminar antes.'),('Complete: If I ___ more confident, I would have offered to help yesterday. (be)','were; was ocorre em uso informal, mas were é modelo aqui.'),('Corrija: If we had tested the sound, we definitely would have prevented the internet outage.','Testing sound does not establish prevention of an internet outage; consequência não sustentada.'),('Formule If only sobre ausência de teste passado.','If only we had tested the equipment.')],
 guided='A defende que baixar arquivo teria garantido evento perfeito; B usa fontes para distinguir uma barreira removida de sucesso total. Depois A reformula sem acusação. B apresenta desejo atual e arrependimento passado. Produzam checklist para próximo encontro, atribuindo responsáveis fictícios, sem marcar tarefas como realizadas.',
 model='A: If we had downloaded it, everything would have worked.\nB: We would have had a local copy, but we hadn’t tested the sound. We can’t claim everything would have worked.\nA: You’re right. I wish we had checked both.\nB: I wish we had a clear procedure now. Let’s write one.\nModelo escrito: The screening did not take place because the online file could not be accessed during the outage. A local copy would have removed that obstacle, but would not guarantee that every other part worked. If we had saved the file, we would have it now. We regret not checking the equipment. The proposed checklist assigns future tasks; it does not establish that any tests have already been completed.',
 transfer='Nova ficção: oficina de desenho tinha materiais para dez, mas doze chegaram. Lista de inscrição com doze estava disponível desde quinta; não foi consultada. Sábado duas pessoas compartilharam lápis. Hoje ainda faltam dois conjuntos; não há evidência de intenção de excluir. A sala comportava doze e estava pronta. Escreva análise de 150–190 palavras: fato, alternativa passada, consequência presente, arrependimento e reparação. Não invente que consultar lista garantiria estoque na loja.',
 evidence='Doze inscritos, dez conjuntos, dois compartilhando; lista ignorada é fato, intenção desconhecida. If we had checked the list, we would have known that twelve people were coming; compra possível não comprovada. If we had obtained two more sets, we would have enough now é hipótese adicional explícita. Não atribuir falha à capacidade da sala.',
 review='Em encontro posterior: convite tinha endereço antigo; ninguém conferiu; três pessoas foram ao lugar errado ontem. Hoje o convite continua sem correção. Formule um arrependimento e uma condicional mista; proponha ação presente.',
 review_answer='I wish we had checked the address. If we had corrected the invitation yesterday, it would show the right address now. Let’s correct it and notify the participants. Não inferir que todos receberam a correção antes de enviá-la.',
 phon='Contraste had CHECKED / would HAVE it NOW; destaque marcadores temporais. O colega classifica passado ou presente a partir de frases completas. Aceite had em forma plena antes de trabalhar contrações ambíguas como we’d.',
 teacher='Separar análise de língua de julgamento moral. A contrafactualidade não autoriza inventar causas. Brasileiros podem misturar would na oração com if e confundir wish had com passado: voltar aos marcadores now/yesterday. Não exigir hipóteses pessoais de arrependimento; usar personagens fictícios. Avaliar se o destinatário distingue fato, hipótese e ação futura. Variar os dados na recuperação antes de repetir o texto.')
]

UNITS += [
 dict(id='B2-03',title='Investigar uma mudança e atribuir relatos com precisão',prerequisites=['B2-02','B1-05','B1-06'],reading_questions=5,
 goal='Comparar relatos de um imprevisto, graduar inferências sobre o passado e transmitir sugestões, negativas e decisões sem alterar a responsabilidade dos participantes.',
 targets=['Modais perfeitos','Passiva de relato','Verbos de relato e complementação'],
 support='timestamp = registro de horário; access log = registro de acesso; deny = negar; suggest = sugerir; persuade = persuadir; report = relato/relatar; evidence = evidência; attachment = anexo; assume = supor; overwrite = sobrescrever; mistake = erro. Fontes e registros abaixo são fictícios e limitados ao cenário.',
 explanation='Must have + particípio indica dedução forte sobre passado, não observação direta: The file must have been changed before ten, se comparação confirma diferença às dez. Might/may have indica possibilidade: Jo might have used an old link. Can’t have rejeita hipótese diante de evidência incompatível: Jo can’t have made the edit with that account at nine if access began at eleven, dentro das condições do cenário. Should have pode avaliar ação esperada: We should have checked the attachment; não afirma que conferimos. It is reported that… / The file is reported to have changed… atribuem relato; a passiva não torna a fonte confiável por si só. Sugestões: suggest checking / suggest that we check, não suggest us to check. Persuade someone to do indica que alguém foi levado a fazer/aceitar; tentativa sem sucesso é try to persuade. Deny changing / deny that one changed relata negativa, sem comprovar inocência.',
 readings=[('Cronologia de um cartaz — cenário fictício','A community gallery planned an opening for six on Friday. On Thursday at eight, the coordinator, Jo, exported a poster showing six. At ten, a second export showed seven. The two exports are available side by side. The editing history records a change from six to seven at nine, made through the shared studio account. Three team members could use that account. The history does not identify which person was at the keyboard.\nJo’s personal account was created at eleven. The administrator confirms that this personal account could not be used before then. That rules out an edit at nine through that particular account. It does not rule out Jo using the shared account, and it does not identify Jo as the editor either.\nAt noon, Mina sent the second export to the mailing list. She later said she had assumed the time was correct because the attachment looked like the final version. The opening itself remained scheduled for six; no booking or organiser’s decision changed it to seven. The wrong time appeared in the poster, not in the venue booking.'),('Ata da conversa e notícia informal','Mina denied changing the time. She acknowledged sending the attachment without checking it against the booking. Jo suggested comparing both exports and sending a correction to the mailing list. The coordinator persuaded the team to send the correction that afternoon; the message was sent at two. Mina also suggested that future exports include a date and a named checker. That procedure has been proposed but has not yet been adopted.\nAn informal message now says, “The opening is reported to have been postponed.” Its author cites the poster with seven, not a decision by the organisers. We should attribute that report and explain why the available records do not support its conclusion. A poster changed, but the booking did not.\nWe should have checked the attachment before sending it. Someone might have mistaken an old discussion about seven for the final decision, but we have no evidence establishing that explanation. The edit must have occurred before ten because the second export already contains it; the log gives the more specific time of nine. Neither the mistaken poster nor the shared login establishes anyone’s intention.' )],
 audio='Interviewer: Can we say Jo changed the time through the personal account at nine?\nAdministrator: No. That account could not be used until eleven. But the shared account was available earlier.\nInterviewer: Mina denied changing it. Does that settle who made the edit?\nAdministrator: No. Her statement is one source, not a complete investigation.\nInterviewer: What did Jo suggest?\nAdministrator: Comparing the exports and sending a correction. The team was persuaded to send it, and did so at two.\nInterviewer: Is the opening reported to have moved to seven?\nAdministrator: Someone has reported that, based on the poster. The booking still says six.',
 questions=[('Que diferença verificável existe entre as duas exportações?','O horário mudou de seis para sete entre as versões das oito e das dez.'),('O registro das nove identifica uma pessoa?', 'Não; identifica conta compartilhada por três membros.'),('Qual hipótese a criação da conta às onze exclui?', 'Edição às nove por aquela conta pessoal; não exclui outros meios de acesso.'),('O que foi realizado e o que continua só proposto na ata?', 'Correção enviada às duas; procedimento de exportação com conferente ainda proposto.'),('Por que a notícia de adiamento não está sustentada?', 'Baseia-se no cartaz; reserva e decisão dos organizadores mantêm seis.'),('Na escuta, a negativa de Mina resolve autoria?', 'Não; é relato, não investigação completa.'),('Qual ação a equipe aceitou e executou?', 'Enviar correção às duas.'),('Qual horário o administrador preserva para a abertura?', 'Seis, conforme reserva.')],
 practice=[('Complete inferência forte: The edit ___ before ten. (happen)','must have happened; a versão das dez já contém a mudança.'),('Apresente causa possível, sem confirmá-la: Someone used an old discussion.','Someone might have used an old discussion.'),('Delimite: Jo can’t have made the edit…','…through the personal account at nine; não ampliar para qualquer conta.'),('Avalie ação não realizada: conferir anexo antes de envio. Use should.','We should have checked the attachment before sending it.'),('Relate com fonte: Someone reports that the opening was postponed.','The opening is reported to have been postponed; acrescentar que fonte é cartaz e que a reserva contradiz a conclusão.'),('Corrija Jo suggested us to compare the files.','Jo suggested comparing the files / suggested that we compare the files.'),('Reescreva Mina said she had not changed it com deny.','Mina denied changing it / denied that she had changed it.'),('Compare persuaded the team to send com tried to persuade the team to send.','Primeira indica persuasão bem-sucedida; segunda só tentativa. Envio efetivo é confirmado separadamente pela ata.'),('Atribua a notícia e a ressalva em duas frases.','It is reported that the opening has been postponed. However, that report relies on the poster, while the booking still shows six.')],
 guided='A recebe cronologia; B recebe ata e notícia informal. A propõe identificar culpado; B pede fonte de cada afirmação. Reconstruam o que está registrado, o que cada pessoa diz e o que é hipótese. Redijam correção pública de 80–110 palavras, sem divulgar acusação individual não sustentada. Façam uma segunda rodada em que o entrevistador confunde conta pessoal com compartilhada.',
 model='A: Jo can’t have changed it at nine, then?\nB: Only through the personal account. The shared account was already available, so that wider conclusion is not supported.\nA: What should we tell visitors?\nB: The opening is at six. The poster contained an error, and a correction was sent.\nModelo escrito: The opening remains scheduled for six on Friday. A poster circulated with seven, but the venue booking was not changed. A correction was sent at two on Thursday. The editing record identifies a shared account, not an individual editor. Mina denied changing the time and acknowledged sending the unchecked attachment. Jo suggested comparing the versions. A new checking procedure has been proposed, but we should not describe it as already in place.',
 transfer='Novo caso fictício: boletim das 9h mostra sala A; versão das 11h mostra B. Histórico registra alteração às 10h pela conta compartilhada. Conta pessoal de Lee só foi ativada ao meio-dia. Reserva permanece A. Nara nega alterar, reconhece enviar versão das 11h. Equipe aceitou enviar correção às 14h, mas ainda são 13h e não houve envio. Escreva síntese de 150–190 palavras: fatos, limites da atribuição, uma hipótese marcada, uma avaliação com should have e ação ainda pendente. Explique em português por que “aceitou enviar” não é “enviou”.',
 evidence='Sala A confirmada, B no boletim; alteração às dez pela conta compartilhada; conta pessoal indisponível até meio-dia; autoria individual desconhecida. Correção futura às 14h ainda não executada. A negativa não é prova conclusiva; hipótese deve permanecer hipótese.',
 review='Em outro encontro: aviso das 8h mostra preço 12; das 10h mostra 15; tabela aprovada mantém 12; mudança às 9h em conta coletiva; pessoa nega editar; correção proposta, não enviada. Formule inferência forte delimitada, relato de negativa e correção de informação.',
 review_answer='The notice must have changed before ten. The person denied editing it, but the shared account does not identify an individual. The approved price remains twelve; the correction has been proposed but not sent. Não inventar motivo nem autor.',
 phon='Faça o parceiro distinguir might have changed, must have changed e should have checked em frases contextualizadas. Primeiro mantenha formas plenas, depois observe ligação natural entre modal e have. O objetivo é recuperar grau de certeza e avaliação, não reproduzir uma redução específica.',
 teacher='Dificuldades previsíveis: traduzir must como obrigação retrospectiva; tratar deny como absolvição; produzir suggest someone to. Use três colunas: registro, relato, inferência. Solicite justificativa para can’t e não aceite escopo maior que a evidência. A atividade não ensina perícia digital: os registros e limites são dados fictícios. Na modalidade autônoma, aluno pode ensaiar os dois papéis, marcando interação como não observada.'),
 dict(id='B2-04',title='Negociar um serviço e acompanhar o que está sendo feito',prerequisites=['B2-03','B1-06'],reading_questions=5,
 goal='Solicitar esclarecimentos com cortesia, distinguir serviço contratado de serviço concluído e descrever intervenções em andamento com agentes claros.',
 targets=['Passiva contínua e agentes','Causativa have/get something done','Distanciamento cortês'],
 support='frame = moldura; mount = montar/fixar; quote = orçamento; approval = aprovação; scratch = risco; collection = retirada; workshop = oficina; fit = instalar/ajustar; carry out = executar; reprint = reimpressão; authorised = autorizado. Serviços e condições são fictícios, sem orientação jurídica.',
 explanation='Am/is/are being + particípio descreve ação recebida em andamento: The frames are being repaired by the workshop. Não equivale a have been repaired, concluído. Was/were being descreve andamento passado: The frames were being checked when Jo called. Have/get + objeto + particípio pode indicar serviço providenciado: We’re having two frames repaired; we got the labels printed. Não significa que fizemos pessoalmente o serviço. Em outro contexto, had a bag stolen descreve ocorrência sofrida, não contratação; a interpretação depende do evento. I was wondering whether… / Would it be possible to… / Could you… atenuam pedido presente; passado em was wondering não precisa situar uma dúvida encerrada no passado. Cortesia não elimina necessidade de explicar objeto, limite e prazo.',
 readings=[('Pedido para uma exposição — ficção','Our photography group has arranged to have two damaged frames repaired. The workshop received them on Monday. On Tuesday morning, the technician wrote: “The frames are being repaired, and the glass is being cleaned. No new glass has been ordered. We will ask for approval if replacement becomes necessary.” The service is in progress; the message does not say the frames are ready to collect.\nThe group also got twenty labels printed by a separate print shop last week. One label contains a date error from the group’s file. The print shop has offered a reprint, but has not started it because the corrected file has not arrived. The repair workshop is not responsible for those labels.\nJo would like to collect everything on Thursday for a Friday exhibition. That is a preferred date, not a date accepted by both suppliers. Before inviting someone to collect the materials, Jo needs confirmation of which items will be ready and where to collect them.'),('Troca entre cliente e oficina','Jo: I was wondering whether the two frames might be ready by Thursday afternoon. Could you confirm what is included in the current quote? We have not approved replacement glass.\nWorkshop: The quote covers frame repair and glass cleaning. One frame is being checked for a loose corner by our technician. The other has been repaired, but we are still checking its finish. We cannot confirm collection of both yet. If new glass is needed, we will send a separate quote before ordering it.\nJo: Thank you. Would it be possible to send an update tomorrow morning? Please keep any glass replacement separate from the work already authorised. We have arranged to have the labels corrected elsewhere, so you do not need to include that in your schedule.\nWorkshop: Yes, we can send an update tomorrow. That is a commitment to provide information, not a guarantee that the repair will be complete. Please wait for a collection confirmation before arranging transport.')],
 audio='Client: Could you clarify whether both frames have been repaired?\nTechnician: One has been repaired and is being checked. The other is still being repaired.\nClient: And the glass?\nTechnician: It is being cleaned. No replacement has been ordered.\nClient: I was wondering whether I could collect both on Thursday.\nTechnician: We can’t confirm that yet. We’ll update you tomorrow morning.\nClient: Understood. We’ve arranged to have the labels corrected by the print shop, not by you.\nTechnician: That helps. Please arrange collection only after confirmation.',
 questions=[('Quais serviços estão autorizados na oficina?', 'Reparo das molduras e limpeza dos vidros; substituição não autorizada.'),('Quem cuida das etiquetas?', 'Gráfica separada, não oficina de molduras.'),('Por que reimpressão ainda não começou?', 'Arquivo corrigido não chegou à gráfica.'),('O que a oficina promete para amanhã?', 'Atualização de informação, não conclusão do reparo.'),('Por que quinta não é data garantida de retirada?', 'É preferência do cliente; oficina ainda não confirmou ambas prontas.'),('Na escuta, qual a diferença de estado entre as molduras?', 'Uma reparada em conferência; outra ainda em reparo.'),('Algum vidro novo foi encomendado?', 'Não.'),('Quando organizar transporte?', 'Depois da confirmação de retirada.')],
 practice=[('Complete ação em andamento: The frames ___ by the workshop. (repair)','are being repaired.'),('Transforme passado: The technician was checking the frame when Jo called.','The frame was being checked by the technician when Jo called.'),('Compare is being cleaned e has been cleaned.','Primeira limpeza em andamento; segunda concluída, com relevância presente.'),('Diga que providenciou impressão por terceiros: We… twenty labels…','We had/got twenty labels printed.'),('Quem executa impressão em We had the labels printed by the shop?', 'A gráfica; we providenciou o serviço.'),('Torne pedido claro e cortês: Send an update tomorrow.','Could you send an update tomorrow? / Would it be possible to send an update tomorrow?'),('I was wondering whether I could collect them now é necessariamente dúvida antiga?', 'Não; pode atenuar pedido atual.'),('Compare had two frames repaired com had a bag stolen.','Primeiro serviço providenciado; segundo evento sofrido, não serviço contratado.'),('Reformule mensagem ambígua They’re doing it com item, estado e agente.','The second frame is being repaired by the workshop; exemplo conforme cenário.')],
 guided='A cliente recebe orçamento e preferência de quinta. B oficina recebe estado dos dois itens e limites de autorização. A pede confirmação de escopo, situação e retirada; B separa atualização e conclusão. Troquem papéis com uma moldura pronta e outra aguardando peça. Produzam registro com responsável, serviço, estado e próxima ação.',
 model='A: I was wondering whether both frames were ready.\nB: One has been repaired and is being checked. The other is still being repaired.\nA: Could you confirm that no replacement glass has been ordered?\nB: Yes. We need separate approval for that.\nModelo escrito: We are having two frames repaired by the workshop. One has been repaired and is being checked; the other is still under repair. Glass cleaning is included, but replacement has not been authorised or ordered. The workshop will send an update tomorrow morning. Thursday collection remains unconfirmed. We have arranged a separate label reprint with the print shop, but still need to send the corrected file before work can begin.',
 transfer='Nova ficção: centro cultural contratou limpeza de três tapetes. Um limpo aguarda secagem; dois estão sendo limpos. Remoção de mancha especial exige orçamento ainda não aprovado. Cliente gostaria de retirada sexta, fornecedor só prometeu atualização quinta. Outra empresa recebeu pedido para lavar cortinas, mas ainda aguarda medidas. Redija pedido cortês e atualização de 150–190 palavras com agentes e estados. Não transforme limpeza em secagem concluída nem solicitação em serviço executado.',
 evidence='Três tapetes, um em secagem, dois em limpeza; serviço especial pendente; sexta é preferência; quinta é atualização. Cortinas a cargo de outra empresa ainda aguardando medidas. Causativa deve indicar providenciar serviço, não execução pessoal.',
 review='No próximo encontro: dois cartazes encomendados; um impresso, outro sendo impresso; laminação não autorizada; retirada desejada terça, sem confirmação. Escreva pergunta cortês e atualização com causativa e passiva contínua.',
 review_answer='We’re having two posters printed. One has been printed; the other is still being printed. Could you confirm when both will be ready? Lamination has not been authorised, and Tuesday collection is not confirmed.',
 phon='Destaque BEING repaired versus HAS BEEN repaired em contraste contextual, sem depender só da velocidade. O parceiro marca em andamento/concluído/em conferência. Ensaie pedido com pausa antes da condição; clareza do limite importa mais que sotaque.',
 teacher='Não ensinar cortesia como uma entonação universal: considerar relação e clareza. Dificuldades previsíveis: omitir being e interpretar have como executar pessoalmente. Faça aluno identificar quem contrata e quem realiza antes de transformar frases. O pedido de reimpressão foi combinado, mas o trabalho ainda não começou; arranged to have não é prova de execução. Diferencie contratação, execução e conclusão também na avaliação.'),
 dict(id='B2-05',title='Transformar notas densas em orientações compreensíveis',prerequisites=['B2-04','B1-06'],reading_questions=5,
 goal='Interpretar grupos nominais e descrições condensadas, reescrevendo orientações para públicos diferentes sem perder agente, restrição ou sequência.',
 targets=['Relativas reduzidas e particípios','Orações participiais e sujeito','Grupos nominais complexos'],
 support='loan = empréstimo; desk = balcão; label = etiqueta; storage = armazenamento; damaged = danificado; checked = conferido; eligible = elegível; portable = portátil; awaiting = aguardando; staff = equipe. “Community equipment loan scheme” tem scheme como núcleo: programa de empréstimo de equipamentos comunitários, não um aparelho.',
 explanation='The cameras stored upstairs equivale neste contexto a cameras that are stored upstairs; the volunteers checking returns equivale a volunteers who are checking returns. Stored/checking modificam nomes diferentes: identificar núcleo e relação antes de reduzir. Em Having checked the label, Jo recorded the return, Jo executa ambas as ações. Evitar Having checked the label, the camera was put away se a câmera parecer sujeito de checked; escrever After Jo checked the label, she put the camera away. Participial inicial normalmente compartilha sujeito com oração principal. Grupos como a two-day equipment loan period condensam relações: núcleo period, duração two-day, finalidade equipment loan. “Two-day” modificador usa day singular; the period lasts two days tem days plural. Nem toda expansão é única: quando relação está ambígua, peça esclarecimento.',
 readings=[('Notas internas de um programa de empréstimos — ficção','The community equipment loan scheme has moved to a ground-floor room. The portable audio recorders stored in the blue cabinet are available for a two-day loan. The cameras awaiting inspection on the upper shelf are not available yet. A green label means that an item has passed the recorded check; it does not guarantee that every possible fault has been excluded.\nVolunteers checking returns must compare the item number with the loan record before changing its status. Having checked the number, they record the return and place the item on the inspection table. They do not put an unchecked item directly into the available stock. Items returned after four are recorded that day but inspected the following morning.\nA draft sign says: “Having recorded the return, the camera can be borrowed again.” That sentence has two problems. It gives the camera an implausible role in recording its own return, and it skips inspection. The intended procedure is: staff record the return; staff inspect the item; only then can an eligible item become available again.'),('Pedido de uma pessoa recém-chegada','I understand that the programme lends equipment, but I find the internal notes difficult to follow. Does “returned equipment inspection table” mean a table that has been returned, or a table where returned equipment is inspected? Please write the relationship out. I also need to know whether the cameras on the upper shelf can be borrowed. Their location alone does not tell me that.\nThe two-day period is clear once you explain it, but the procedure after return needs separate steps. If I bring an item back at four thirty, it will be recorded today and inspected tomorrow morning. It should not be shown as available merely because I handed it over.\nA shorter sign would help: “Return equipment at the desk. Staff will record it and inspect it before making it available again. Cameras awaiting inspection cannot be borrowed. Returns after four are inspected the following morning.” Please keep the distinctions that affect what people can do; do not shorten the message so much that its conditions disappear.')],
 audio='Visitor: Can I borrow a camera from the upper shelf?\nVolunteer: Those cameras are awaiting inspection. They aren’t available yet.\nVisitor: What about the recorders stored in the blue cabinet?\nVolunteer: They’re available for a two-day loan.\nVisitor: If I return one at four thirty, can someone else borrow it immediately?\nVolunteer: No. We record the return that day, but inspect it the next morning.\nVisitor: So recording a return is not the same as approving the item?\nVolunteer: Exactly. Staff carry out the inspection before changing its availability.',
 questions=[('O que o núcleo scheme nomeia no primeiro grupo nominal?', 'Programa de empréstimo; não equipamento individual.'),('Quais itens estão disponíveis e quais aguardam inspeção?', 'Gravadores no armário azul disponíveis; câmeras da prateleira superior aguardam inspeção.'),('Quais dois problemas há no cartaz em rascunho?', 'Sujeito implícito de recording parece câmera; disponibilidade omite inspeção.'),('Como interpretar inspection table no contexto?', 'Mesa onde equipamentos devolvidos são inspecionados, não mesa devolvida.'),('A etiqueta verde garante ausência de todo defeito possível?', 'Não; indica aprovação na conferência registrada.'),('Na escuta, qual período de empréstimo dos gravadores?', 'Dois dias.'),('Quando item devolvido às 16h30 será inspecionado?', 'Na manhã seguinte.'),('Quem executa inspeção antes de mudar disponibilidade?', 'Equipe, não o usuário por simplesmente devolver.')],
 practice=[('Expanda cameras awaiting inspection.','cameras that are awaiting inspection.'),('Reduza recorders that are stored in the blue cabinet sem mudar sentido.','recorders stored in the blue cabinet.'),('Expanda volunteers checking returns.','volunteers who are checking returns.'),('Quem conferiu em Having checked the number, Jo recorded the return?', 'Jo; sujeito compartilhado.'),('Corrija Having checked the label, the camera was stored away para manter agente humano explícito.','After Jo checked the label, she stored the camera away; conferir também se inspeção necessária ocorreu no cenário.'),('Identifique núcleo em a two-day equipment loan period.','period; duração de dois dias e finalidade empréstimo de equipamento.'),('Corrija a two-days loan period.','a two-day loan period; days permanece em The period lasts two days.'),('Expanda returned equipment inspection table de modo inequívoco.','a table for inspecting equipment that has been returned.'),('Reduza cartaz mantendo condição da inspeção, em até duas frases.','Return equipment at the desk. Staff inspect returned items before making them available again; acrescentar regra das 16h se esse for o cartaz completo.')],
 guided='A recebe notas internas; B é visitante com três dúvidas: câmeras, prazo e devolução após quatro. A explica oralmente sem ler blocos nominais inteiros. B registra ações possíveis e pede esclarecimento. Depois revisem o cartaz defeituoso e produzam uma versão completa em quatro frases, preservando a exceção de horário.',
 model='B: Can I borrow the cameras awaiting inspection?\nA: No. That means the cameras which still need inspection. The recorders in the blue cabinet are available for two days.\nB: Does returning one make it available again?\nA: Not immediately. Staff record and inspect it first.\nModelo escrito: You can borrow the audio recorders in the blue cabinet for two days. Cameras awaiting inspection are not available. Return items at the desk; staff will record and inspect them before making them available again. Items returned after four are inspected the following morning. The green label records the completed check and does not promise the absence of every possible fault.',
 transfer='Novo programa fictício empresta instrumentos por três dias. Violões guardados no armário A foram conferidos e estão disponíveis; teclados na mesa de inspeção aguardam teste. Devoluções depois das 15h são registradas no mesmo dia e testadas no dia seguinte. Rascunho: Having recorded the return, the keyboard is ready to borrow. Escreva orientação de 130–170 palavras e uma explicação em português da correção. Use um grupo nominal, uma relativa reduzida e uma oração participial com sujeito claro, sem condensar tudo numa frase.',
 evidence='Violões disponíveis três dias; teclados aguardam teste; após 15h registro hoje/teste amanhã. Frase participial deve atribuir ação à equipe. Modelo possível: Having recorded the return, staff place the keyboard on the inspection table. Não tornar teclado disponível antes do teste.',
 review='Em outro encontro: laptops na mesa verde aguardam limpeza; tablets no armário estão disponíveis por um dia. Reescreva The tablets that are stored in the cupboard…; corrija Having cleaned the laptop, the label was attached usando agente humano. Explique o núcleo de a one-day tablet loan.',
 review_answer='The tablets stored in the cupboard are available for a one-day loan. Having cleaned the laptop, the technician attached the label. Loan é o núcleo; one-day duração e tablet item emprestado. Não afirmar que limpeza já ocorreu nos laptops aguardando-a: frase corrigida é exemplo hipotético, não atualização do estoque.',
 phon='Faça pausas em grupos de sentido: cameras / awaiting inspection; recorders / stored in the blue cabinet. Depois reexpresse com that are para conferir compreensão. O ouvinte identifica item, estado e local; velocidade não é objetivo.',
 teacher='Evitar ensinar que qualquer sequência nominal admite uma única tradução palavra por palavra. Peça ao aluno marcar núcleo e explicitar relações. Brasileiros podem atribuir sujeito impessoal ao particípio inicial; contrastar quem realiza cada ação. A forma condensada é recurso opcional para clareza, não obrigação de tornar textos mais densos. Na transferência, aceitar versão expandida eficaz e registrar uso de redução como ainda não observado, sem apagar sucesso comunicativo.')
]

UNITS += [
 dict(id='B2-06',title='Relatar resultados sem ampliar o alcance dos dados',prerequisites=['B2-05','B1-04'],reading_questions=5,
 goal='Distinguir generalização de descrição de um grupo, interpretar quantificadores e posicionar only para comunicar exatamente a restrição pretendida.',
 targets=['Artigos em generalizações','Quantificação de alcance','Posição e alcance de only'],
 support='respondent = respondente; sample = amostra; household = domicílio; claim = alegação; funding = financiamento; attendance = presença; survey = levantamento; scope = alcance. Os dados são fictícios; opiniões dos respondentes não representam automaticamente uma população maior.',
 explanation='Plural ou incontável sem artigo pode generalizar: Libraries provide access to information; information can be useful. The identifica conjunto recuperável: the libraries in this survey; the information on this form. A/an + singular pode apresentar um membro típico: A library can be a meeting place. The + singular também ocorre em certas generalizações de espécie ou invenção, como The tiger is a large cat; não é substituto automático para qualquer plural genérico. Most people fala de maioria de um conjunto dado pelo contexto; most of the respondents explicita conjunto definido. Não usar most of respondents. All respondents / all the respondents / all of the respondents são possíveis conforme referência; com pronome, all of them, não all them. None of the twelve respondents indica zero nesse grupo. None pode admitir verbo singular ou plural conforme referência e uso: None of the information is new; None of the respondents is/are available. A great deal of acompanha incontável: a great deal of time, não a great deal of books. Only pode limitar sujeito, objeto ou tempo: Only Jo called; Jo called only Ana; Jo called on Tuesday only. A posição junto ao foco ajuda; Jo only called pode depender da ênfase oral. Em texto, reescreva em vez de depender de entonação ausente.',
 readings=[('Relatório de uma biblioteca — ficção','Libraries can provide places to read, study and meet other people. That general statement introduces our topic; it is not a finding from our small survey. Our survey concerned the two libraries in the Riverside project. We invited twenty registered users to respond, and twelve did. Eight of the twelve respondents preferred a later closing time. Four preferred the current time. We did not collect answers from the other eight invited users.\nMost of the respondents preferred later closing. We cannot replace that sentence with “Most residents prefer later closing”: the survey did not establish the views of all residents. All twelve respondents used at least one of the two libraries, but none of them was asked about weekend opening. Silence on weekends therefore does not show opposition to weekend opening.\nThe team spent a great deal of time comparing the forms. The information on those forms helps describe the respondents, but more information would be needed before making broader claims. No funding decision has been made. The report recommends discussing a trial; it does not say a trial has been approved.'),('Revisão do anúncio público','A draft announcement reads: “Most residents want longer hours. We only surveyed registered users on Tuesday. All users support a weekend trial.” Each sentence needs attention. The first turns results from twelve respondents into a claim about residents. The third invents a weekend question and confuses respondents with all users.\nThe middle sentence is less obviously wrong, but it is unclear what only is restricting. The survey team confirms three facts: only registered users were invited; invitations were sent on Tuesday and Wednesday; answers were accepted throughout the week. If the intended restriction concerns who was invited, write “We invited only registered users to take part.” Do not suggest that the survey happened only on Tuesday.\nThe revised notice should give the numbers and the population: “Eight of the twelve respondents preferred later closing. Twenty registered users were invited; eight did not respond. Weekend opening was not included in the questions. The team recommends discussing a trial, but no trial or funding has been approved.” This wording is less dramatic, but readers can see what the evidence actually covers.')],
 audio='Editor: Can we say most residents want longer hours?\nResearcher: No. Eight of twelve respondents preferred later closing. We invited twenty registered users.\nEditor: Did all twenty answer?\nResearcher: No, only twelve did.\nEditor: So none of the others supported the idea?\nResearcher: We don’t know. They did not respond.\nEditor: Was Tuesday the only invitation day?\nResearcher: No. We sent invitations on Tuesday and Wednesday. Only registered users were invited.\nEditor: And weekends?\nResearcher: None of the respondents was asked about weekend opening.',
 questions=[('Qual frase inicial é generalização, não resultado da pesquisa?', 'Libraries can provide places to read, study and meet other people.'),('Qual é o conjunto em most of the respondents?', 'Os doze respondentes; oito preferiram fechar mais tarde.'),('O que sabemos das oito pessoas que não responderam?', 'Foram convidadas e não responderam; preferência desconhecida.'),('Por que none of them was asked não significa oposição?', 'Pergunta sobre fins de semana não foi feita.'),('O que only deve limitar no anúncio corrigido?', 'Quem foi convidado: usuários cadastrados, não apenas terça.'),('Quantas pessoas responderam na escuta?', 'Doze de vinte convidadas.'),('Quais foram os dias de envio dos convites?', 'Terça e quarta.'),('Que informação sobre fins de semana está ausente?', 'Preferências, pois ninguém foi perguntado sobre esse tema.')],
 practice=[('Escolha generalização sem conjunto definido: Libraries / The libraries can be meeting places.', 'Libraries; the libraries precisaria de referência específica neste contexto.'),('Escolha para dados do formulário citado: Information / The information on this form is incomplete.', 'The information; conjunto identificado pelo formulário.'),('Explique The tiger is a large cat: exige um tigre individual conhecido?', 'Não; pode representar a espécie nesse padrão. Tigers are large cats é alternativa genérica.'),('Corrija Most of respondents wanted later closing.', 'Most of the respondents wanted later closing / Most respondents wanted later closing.'),('Substitua all the respondents por pronome.', 'all of them; não all them.'),('Complete: a great deal of time / books.', 'time; incontável. Para livros, many books / a large number of books.'),('Complete e explique: None of the information ___ new.', 'is; information é incontável.'),('None of the respondents is/are available: só uma concordância é admissível?', 'Ambas ocorrem; singular ou plural conforme construção e uso. Não marcar plural automaticamente como erro.'),('Restrinja o destinatário: Jo ligou para Ana e ninguém mais.', 'Jo called only Ana; explicitar Jo called Ana and no one else também é válido.'),('Restrinja o sujeito: só Jo ligou para Ana.', 'Only Jo called Ana.'),('Reescreva We only sent invitations on Tuesday para deixar inequívoco que terça foi o único dia, num cenário diferente.', 'We sent invitations on Tuesday and on no other day / Tuesday was the only day we sent invitations. Não aplicar esse dado ao caso real da unidade.'),('Transforme all users support weekends em afirmação fiel às fontes.', 'We did not ask about weekend opening; não há dado de apoio ou oposição.')],
 guided='A recebe relatório; B recebe anúncio em rascunho. B tenta publicar as três frases. A aponta população, denominador e alcance de only, propondo correção. Depois troquem: A produz frase curta e B pergunta quem, quantos e quando. Mantenham a diferença entre não responder e responder não.',
 model='A: Most of the respondents preferred later closing.\nB: Does that mean most residents did?\nA: No. Twelve people responded, and eight chose later closing. We don’t know the views of the non-respondents.\nB: What does only refer to?\nA: The invited group: registered users. Invitations went out on two days.\nModelo escrito: Libraries can serve different community needs. In this survey, eight of twelve respondents preferred later closing at the two project libraries. Twenty registered users were invited, so eight did not respond. Their preferences remain unknown. Only registered users were invited; invitations were sent on Tuesday and Wednesday. The survey did not ask about weekend opening. A trial has been proposed for discussion, but neither approval nor funding is confirmed.',
 transfer='Novo levantamento fictício de oficina cultural: 30 inscritos convidados segunda e quinta; 18 respostas; 12 preferem encontros de manhã e seis à tarde. Não houve pergunta sobre aulas online. Só inscritos receberam convite; nenhuma mudança de agenda aprovada. Escreva notícia de 140–180 palavras com uma generalização identificada, dados específicos, quantificadores e restrição inequívoca com only. Explique por que doze não respondentes não podem ser classificados como contrários.',
 evidence='Trinta convidados, dezoito respostas, doze manhã/seis tarde; doze sem resposta, não doze contrários. Convites em dois dias, somente inscritos. Online e mudança de agenda não confirmados. Não generalizar para cidade ou todos os estudantes.',
 review='No encontro seguinte: dez pessoas convidadas, seis respostas, quatro favoráveis; só associados convidados, convites sexta e sábado; orçamento não perguntado. Produza duas frases de resultado e uma de limite com none of ou only.',
 review_answer='Four of the six respondents supported the idea. Ten members were invited, and four did not respond. Only members were invited; invitations went out on Friday and Saturday. None of the respondents was asked about the budget. Não inferir apoio das quatro pessoas sem resposta.',
 phon='Leia Only JO called Ana / Jo called only ANA. O parceiro diz o que foi excluído e depois lê versão inequívoca escrita. Pratique pausa entre eight of twelve e twenty invited para conservar denominadores.',
 teacher='Conferir aritmética antes de avaliar forma. Dificuldades previsíveis: the em generalizações por transferência do português; most of sem determinante; only ligado mecanicamente ao verbo. Não transformar exemplos de espécie em regra universal para the. Nas variantes de none, avaliar referência e naturalidade, sem impor singular em todos os casos. Aceitar generalização prudente como contexto, mas não como resultado provado pela amostra.'),
 dict(id='B2-07',title='Defender uma posição e explicitar condições',prerequisites=['B2-06','B2-02'],reading_questions=5,
 goal='Reparar mal-entendidos com foco e ênfase, distinguir concessão factual de hipótese e escolher entre formulação enfática e neutra conforme o público.',
 targets=['Ênfase com do e clefts','Inversão após negativos','Concessão e condição delimitada'],
 support='draft = rascunho; final version = versão final; venue = local; forecast = previsão meteorológica; shelter = abrigo; approval = aprovação; access check = conferência de acesso; withdraw = retirar; committee = comissão. Decisões são fictícias; condições logísticas pertencem apenas ao cenário.',
 explanation='Do/does/did + verbo base pode enfatizar uma afirmação: We do support the event; Jo did send a draft. Não usar did sent. It-cleft destaca termo: It was a draft that Jo sent, not a final plan. What-cleft destaca necessidade ou resultado: What we need is a confirmed room. Ênfase não acrescenta prova. Após negativos/restritivos iniciais, ocorre inversão em padrões como Never have we approved this; Not only did Jo send the draft, but she also called; Only after the check did we approve the room. Em Not until Thursday did we receive approval, a inversão fica na oração principal. Não inverter quando only modifica sujeito: Only Jo called, não Only did Jo call. Sujeito negativo também não exige inversão: Nobody called. Even though apresenta contraste factual: Even though it rained, we met indoors. Even if considera hipótese: Even if it rains, we’ll meet indoors. Provided that / as long as podem estabelecer condição: We can use the room provided that access is confirmed. As long as também pode significar duração em outros contextos; conferir sentido. Unless expressa exceção/condição negativa já estudada. Não converter condição em fato realizado.',
 readings=[('Resposta à comissão — ficção','We do support the community reading event. Our concern is the venue, not the purpose of the meeting. Jo sent a draft on Monday. It was a draft that she sent, not a final plan. The committee asked for confirmation of room access before approving the venue. What we need now is that confirmation, not another statement that everyone likes reading.\nLast year, even though it rained, the group met indoors because a room had already been confirmed. This year’s outdoor area has been suggested, but the indoor alternative has not yet been approved. Even if the forecast improves, we still need a workable alternative. Better weather does not confirm a room.\nThe committee can approve the plan provided that the access check is completed and the indoor room is confirmed by Thursday. Those are two conditions. At present, neither has been completed. The event remains a proposal under review; support for its purpose is not permission to announce the venue as settled.'),('Duas versões de uma atualização','A formal note from the committee says: “Never have we approved an unconfirmed venue for this project. Not only did Jo send the draft, but she also called to ask about access. Only after both checks are complete will we approve this year’s plan.” These sentences emphasise policy and sequence. They do not say that the checks are already complete.\nFor volunteers, a less formal version may be clearer: “We have not approved the venue. Jo sent a draft and called about access. We will approve the plan only after the access check and room confirmation are complete.” Neither version should be shortened to “Jo has secured approval.”\nA separate example describes last year: “Not until Thursday did we receive the room confirmation.” Here Thursday belongs to a completed past event. In this year’s instructions, Thursday is a deadline for conditions that remain open. A reader must not combine the examples into a claim that this year’s room was confirmed last Thursday.\nOne committee member adds, “Only Jo called us.” That identifies who called; it does not need auxiliary inversion. Another says, “Nobody objected to reading as an activity.” That also leaves the subject before the verb. The disagreement concerns the plan’s readiness, not opposition to reading.')],
 audio='Volunteer: I heard the committee doesn’t support the event.\nCoordinator: We do support it. What we need is a confirmed indoor room and a completed access check.\nVolunteer: But Jo sent the plan.\nCoordinator: It was a draft that Jo sent, not the final plan.\nVolunteer: If the forecast improves, can we announce the venue?\nCoordinator: Even if it improves, those conditions still apply.\nVolunteer: Has either condition been completed?\nCoordinator: Not yet. Only after both are complete will the committee approve the plan.',
 questions=[('Qual oposição real a comissão faz?', 'Apoia finalidade, mas distingue apoio de aprovação de local ainda pendente.'),('O que Jo enviou?', 'Rascunho, não plano final.'),('Por que even though é adequado à referência ao ano anterior?', 'Chuva e encontro interno são fatos narrados, não hipótese.'),('Quais duas condições faltam para aprovação?', 'Conferência de acesso e confirmação da sala interna até quinta.'),('O que torna a frase sobre quinta do ano anterior diferente do prazo atual?', 'Uma é evento passado concluído; outra prazo futuro para pendências.'),('Na escuta, o que a comissão afirma apoiar?', 'O evento/finalidade.'),('Melhora da previsão elimina condições?', 'Não.'),('Qual condição já foi concluída na escuta?', 'Nenhuma das duas.')],
 practice=[('Enfatize Jo sent a draft com did.', 'Jo did send a draft; base send após did.'),('Destaque draft com it-cleft.', 'It was a draft that Jo sent, not a final plan.'),('Destaque necessidade: We need room confirmation, usando What.', 'What we need is room confirmation.'),('Corrija Never we have approved that venue.', 'Never have we approved that venue.'),('Comece Jo sent the draft and called com Not only.', 'Not only did Jo send the draft, but she also called.'),('Comece We received confirmation only on Thursday com Not until.', 'Not until Thursday did we receive confirmation.'),('Corrija Only after the checks we will approve the plan.', 'Only after the checks will we approve the plan.'),('Only Jo called e Nobody called precisam de inversão?', 'Não; only modifica sujeito e nobody é sujeito negativo. Manter sujeito-verbo.'),('Escolha para chuva já ocorrida: Even if / Even though it rained, we met indoors.', 'Even though; contraste factual.'),('Escolha para chuva possível: Even if / Even though it rains tomorrow, the indoor meeting can proceed.', 'Even if; hipótese.'),('Combine aprovação e duas condições com provided that.', 'The committee can approve the plan provided that access is checked and the room is confirmed.'),('Reescreva Never have we approved this venue em tom neutro.', 'We have never approved this venue. Escolha registro pelo público, não por suposta superioridade.')],
 guided='A é voluntário que interpreta pedido de revisão como rejeição do evento. B representa comissão e usa cleft ou do enfático para reparar o mal-entendido. A pergunta sobre previsão e prazo; B distingue concessão e condição. Escrevam duas versões da mesma atualização, uma enfática e outra neutra, explicando qual enviariam ao grupo e por quê.',
 model='A: So you don’t want the event?\nB: We do want it. What we need is a confirmed venue.\nA: But it may not rain.\nB: Even if it stays dry, the conditions still apply. It was a draft that Jo sent. We haven’t approved the final plan.\nModelo escrito: The committee supports the reading event, but the venue remains unconfirmed. Jo sent a draft and called about access. Approval depends on both the access check and confirmation of the indoor room by Thursday. Even if the weather forecast improves, these conditions remain. Last year’s room confirmation does not establish this year’s arrangements. Please describe the plan as under review until the committee confirms approval.',
 transfer='Novo caso: grupo apoia oficina sábado. Lia enviou lista preliminar, não inscrição final. Aprovação depende de equipamentos conferidos e instrutor confirmado até sexta. Equipamentos já conferidos, instrutor ainda não confirmou. Ano passado houve atraso de ônibus, mas oficina ocorreu com instrutor substituto. Escreva atualização de 140–180 palavras com foco em lista preliminar, concessão factual e condição pendente; acrescente versão oral neutra de uma frase com inversão. Não afirmar que ambas as condições continuam pendentes.',
 evidence='Lista preliminar, não inscrição; equipamentos concluídos, instrutor pendente. Even though houve atraso descreve passado; even if sobre eventualidade futura não confirma substituto atual. Only after the instructor is confirmed will… pode expressar condição restante, preservando prazo sexta.',
 review='No próximo encontro: autorização depende de sala e materiais; sala confirmada, materiais não; anúncio enviado era proposta. Redija reparação com cleft e frase com only after, seguida de versão neutra.',
 review_answer='It was a proposal that we sent, not a final announcement. Only after the materials are confirmed will we approve the plan. We will approve the plan only after the materials are confirmed; sala já resolvida, não reinserir como pendência.',
 phon='Contraste We DO support it e It was a DRAFT that Jo sent. Peça ao colega identificar o mal-entendido corrigido. Leia versão enfática e neutra de inversão sem associar volume alto a argumentação melhor.',
 teacher='Ensinar inversão como opção de registro com limites, não como regra para qualquer advérbio inicial. Comparar only after com only Jo e nobody. Na escrita aberta, aceitar versão neutra clara e registrar inversão não observada se ausente. Dificuldades previsíveis: did sent, inversão na oração temporal inteira e troca de even if/even though. As duas condições devem ser acompanhadas separadamente; recuperação altera qual delas já foi cumprida.'),
 dict(id='B2-08',title='Explicar adaptação e tornar decisões transparentes',prerequisites=['B2-07','B1-07','B2-05'],reading_questions=5,
 goal='Comparar hábitos antigos e adaptação atual, recuperar informações omitidas num diálogo e reescrever decisões nominais preservando agentes e estado de execução.',
 targets=['Referência e elipse','Be/get used to e accustomed','Categorias e nominalização inicial'],
 support='rota = escala; adjustment = ajuste; approval = aprovação; implementation = implementação; expansion = expansão; accessible = acessível; accessibility = acessibilidade; familiar = familiar; accustomed = acostumado; shift = turno. Os usos de accessibility abaixo se referem à compreensão de instruções, não certificam acessibilidade de um serviço.',
 explanation='Elipse evita repetição se o conteúdo é recuperável: Jo can attend, but Lee can’t [attend]. Jo has read the notice; Lee hasn’t [read the notice]. So do I / Neither do I acompanham auxiliar e polaridade: I work mornings — So do I; I can’t come — Neither can I. I think so / I hope so retomam uma proposição; I don’t think so / I hope not são negativas usuais. Se há duas perguntas, so pode ficar ambíguo: explicitar a qual responde. Used to + base descreve hábito/estado passado: I used to work nights. Be used to + nome/-ing descreve familiaridade: I’m used to working mornings. Get used to destaca adaptação: I’m getting used to the new rota; ainda não implica adaptação concluída. Be accustomed to + nome/-ing é alternativa frequentemente mais formal. To aqui é preposição, não infinitivo. Nominalização muda construção: approve → approval, decide → decision, implement → implementation; accessible → accessibility muda adjetivo em nome. Sufixos não são fórmula universal para criar palavras: aprender formas e padrões em contexto. The coordinator approved the rota → The coordinator’s approval of the rota preserva agente. Approval was given omite quem; recuperar se fonte o identifica. Uma nominalização pode condensar informação, mas também esconder agente, data e execução. Approval of the expansion não significa implementation of the expansion.',
 readings=[('Diário de adaptação — ficção','I used to work evening shifts at the community studio. This month I moved to mornings. I’m getting used to starting at eight, but I still need to prepare my bag the night before. I’m already used to checking the equipment at the start of a shift; that part of the job has not changed. My colleague Lee is accustomed to working mornings, so Lee has offered to explain the new rota.\nLast Monday, I said, “I’ve read the new notice.” Lee replied, “I haven’t.” That meant Lee had not read that notice, not that Lee had never read any notice. Later I said, “I can attend the briefing.” Lee said, “So can I.” We both meant the same briefing on Wednesday. The short replies worked because the action and event were clear.\nThen I asked, “Has the expanded timetable been approved, and has it started?” Lee answered, “I think so.” That was not clear enough: approval and implementation are different. We checked the coordinator’s message together instead of guessing what so referred to.'),('Mensagem da coordenação e revisão de texto','The coordinator approved an expansion of the morning timetable on Tuesday. It will begin next month, after the rota is finalised. The coordinator has not changed the current opening hours. Approval has happened; implementation has not. Staff can comment on the draft rota until Friday.\nA summary says, “Following approval, implementation and adjustment were completed.” This sounds official, but it changes the facts. The coordinator approved the expansion; no one has implemented it yet. Staff are still adjusting to their current shifts, and the proposed new rota is not final. The abstract nouns hide the separate people, actions and dates.\nA clearer version is: “The coordinator approved the timetable expansion on Tuesday. It has not started. Staff may comment on the draft rota until Friday; the new timetable is due to begin next month.” Nominal forms are not forbidden: “The coordinator’s approval of the expansion” can be useful when the agent stays visible. The choice should help the reader understand who did what and what remains to happen. Clear instructions may improve accessibility, but the adjective accessible and the noun accessibility still need a specific context; neither proves that every person can use the service without barriers.')],
 audio='Worker: I used to work evenings. I’m still getting used to the morning shift.\nColleague: I’m accustomed to mornings, but I’m not used to this new rota yet.\nWorker: I can attend Wednesday’s briefing.\nColleague: So can I.\nWorker: Has the expansion been approved?\nColleague: Yes, it has.\nWorker: Has it started?\nColleague: No, it hasn’t. Approval was on Tuesday; the start is planned for next month.\nWorker: I hope the draft rota stays open for comments until Friday.\nColleague: It does. The coordinator’s message confirms that deadline.',
 questions=[('Qual hábito antigo mudou e qual procedimento continua familiar?', 'Turno noturno mudou para manhã; conferir equipamento no início continua familiar.'),('Getting used to prova adaptação concluída?', 'Não; apresenta processo de adaptação.'),('O que Lee omite em I haven’t no diário?', 'Read the new notice; não nega leitura de todo e qualquer aviso.'),('Por que I think so ficou ambíguo?', 'Duas perguntas: aprovação e início; resposta não distingue ambas.'),('Que fatos a nominalização da síntese adulterou?', 'Implementação e ajuste não concluídos; só aprovação ocorreu.'),('Na escuta, a que So can I se refere?', 'Poder comparecer à reunião de quarta.'),('Quando expansão foi aprovada e quando deve começar?', 'Aprovada terça; início previsto mês seguinte.'),('Qual prazo para comentar rascunho?', 'Até sexta.')],
 practice=[('Expanda Lee hasn’t em Jo has read the notice; Lee hasn’t.', 'Lee hasn’t read the notice.'),('Responda concordância a I work mornings com so.', 'So do I.'),('Responda concordância a I can’t attend com neither.', 'Neither can I.'),('Negue expectativa: Will it be cancelled? I hope ___.','not; I hope not.'),('Duas perguntas recebem I think so. Como reparar?', 'Pedir Which point do you mean? ou responder cada proposição explicitamente.'),('Complete hábito passado: I used to ___ evenings. (work)', 'work; verbo base.'),('Complete familiaridade: I’m used to ___ early. (start)', 'starting; to preposição.'),('Compare I’m getting used to mornings e I’m used to mornings.', 'Primeira processo de adaptação; segunda familiaridade já estabelecida.'),('Reescreva familiaridade em registro mais formal com accustomed.', 'I’m accustomed to working mornings / to morning shifts.'),('Nominalize The coordinator approved the expansion sem ocultar agente.', 'The coordinator’s approval of the expansion; fragmento nominal a inserir numa frase, não oração completa.'),('Transforme accessible em nome e approve em nome.', 'accessibility e approval; não assumir sufixo único para ambos.'),('Reescreva Implementation was completed conforme fonte.', 'The coordinator approved the expansion, but it has not been implemented yet.')],
 guided='A é trabalhador novo que faz duas perguntas juntas sobre aprovação e início. B responde primeiro com so; A pede esclarecer antecedente. Depois B separa estados usando auxiliares sem repetir tudo. Comparem rotina antiga, adaptação e procedimento familiar. Por fim, reescrevam a síntese nominal para a equipe, indicando agente e prazo.',
 model='A: Has it been approved, and has it started?\nB: I think so.\nA: Which part do you mean?\nB: It has been approved, but it hasn’t started.\nA: Thanks. I’m still getting used to mornings.\nB: I’m accustomed to mornings, but I’m not used to the new rota yet.\nModelo escrito: The coordinator approved the morning timetable expansion on Tuesday. It has not been implemented; the start is planned for next month, after the rota is finalised. Staff can comment until Friday. The writer used to work evenings and is still getting used to mornings. Familiarity with routine equipment checks does not mean everyone is accustomed to the new timetable. The coordinator’s approval is a completed decision, while implementation remains a future step. Please keep those stages separate in summaries.',
 transfer='Nova equipe fictícia: Eva trabalhava presencialmente, agora está se adaptando a encontros online; já tem familiaridade com escrever atas. Rui está acostumado a encontros online, mas não ao novo calendário. Diretora aprovou extensão do atendimento na quarta; início previsto daqui a duas semanas, calendário ainda em consulta até segunda. Escreva atualização de 140–180 palavras com hábitos/adaptação, decisão nominal com agente explícito e estados separados. Acrescente diálogo curto com uma elipse clara e reparação de I think so após duas perguntas.',
 evidence='Eva used to work in person, is getting used to online meetings, is used to taking minutes. Rui accustomed to online meetings, not new schedule. Aprovação quarta pela diretora, início futuro; consulta até segunda. Elipse precisa de antecedente único ou reparação. Não tratar familiaridade digital como adaptação universal.',
 review='No encontro seguinte: Jo costumava começar 9h, adapta-se a 7h, já está acostumado a atender por telefone. Plano aprovado ontem pelo gerente, ainda não iniciado. Escreva três frases e uma dupla pergunta seguida de resposta explícita.',
 review_answer='Jo used to start at nine and is getting used to starting at seven. Jo is already used to speaking to customers on the phone. The manager’s approval of the plan was recorded yesterday; implementation has not started. Has it been approved, and has it started? It has been approved, but it hasn’t started.',
 phon='Contraste I USED TO work / I’m USED TO working / I’m GETTING USED TO working em frases completas. Na elipse, mantenha auxiliar audível: has / hasn’t, can / can’t. O ouvinte reconstrói a ação omitida antes de repetir.',
 teacher='Distribua os papéis do trabalhador e de Lee; preserve familiaridade com manhã e adaptação à escala como informações distintas. Dificuldades previsíveis: to work depois de be used to; tratar toda nominalização como palavra abstrata sem agente; so depois de várias perguntas. Ensinar forma e função sem exigir estilo burocrático. Na autoavaliação, distinguir significado recuperado de forma usada produtivamente. Aprovação do currículo ou de um plano nunca equivale a execução só porque foi nominalizada.')
]
